/**
 * Raw research list with `nameRu` resolved from the translation map. Entries whose
 * Russian name is missing fall back to the English one, so a name is always shown.
 */
export const gtnhResearchLocalized = gtnhResearch.map((r) => ({
    ...r,
    nameRu: translated[r.name] || r.nameRu || '',
}));

/**
 * The research name that should be displayed for the given language.
 * Falls back to the English name when no translation exists.
 */
export function getResearchDisplayName(research, lang = 'ru') {
    if (lang === 'en') return research.name;
    return research.nameRu || research.name;
}

/**
 * Search over both language versions: a query typed in Russian matches `nameRu`,
 * a query typed in English still matches the original `name`.
 */
export function searchResearch(query, lang = 'ru') {
    const q = String(query || '').trim().toLowerCase();
    if (!q) return [];
    return gtnhResearchLocalized.filter((r) => {
        if (r.name.toLowerCase().includes(q)) return true;
        if (lang !== 'en' && r.nameRu && r.nameRu.toLowerCase().includes(q)) return true;
        return false;
    });
}
